from typing import List

def criticalConnections(V: int, adj: List[List[int]]) -> List[List[int]]:
    def dfs(node, parent, low, disc, time, stack, visited, bridges):
        nonlocal timer
        visited[node] = True
        disc[node] = low[node] = timer
        timer += 1
        stack.append(node)

        for neighbor in adj[node]:
            if neighbor == parent:
                continue
            if not visited[neighbor]:
                dfs(neighbor, node, low, disc, time, stack, visited, bridges)
                low[node] = min(low[node], low[neighbor])

                if low[neighbor] > disc[node]:
                    bridges.append(sorted([node, neighbor]))
            else:
                low[node] = min(low[node], disc[neighbor])

        if low[node] == disc[node]:
            while stack[-1] != node:
                stack.pop()
            stack.pop()

    timer = 0
    visited = [False] * V
    disc = [-1] * V
    low = [-1] * V
    stack = []
    bridges = []

    for i in range(V):
        if not visited[i]:
            dfs(i, -1, low, disc, timer, stack, visited, bridges)

    return sorted(bridges)
